import urllib.request
import csv
from collections import defaultdict
import datetime

def parse_date(s):
    s = s.strip()
    # try formats: YYYY/MM/DD, YYYY-MM-DD, M/D, MM/DD
    for fmt in ('%Y/%m/%d', '%Y-%m-%d', '%m/%d', '%Y/%m/%d %H:%M:%S', '%Y-%m-%d %H:%M:%S'):
        try:
            dt = datetime.datetime.strptime(s, fmt)
            if dt.year == 1900:
                dt = dt.replace(year=2026) # or assume current year/2025/2026
            return dt
        except ValueError:
            continue
    # try slash M/D
    parts = s.split('/')
    if len(parts) == 2:
        try:
            m = int(parts[0])
            d = int(parts[1])
            # default to 2026 or 2025 depending on month
            y = 2026 if m >= 3 else 2026
            return datetime.datetime(y, m, d)
        except ValueError:
            pass
    return None

urls = [
    ('Sheet 1 (A col)', 'https://docs.google.com/spreadsheets/d/1tjiYmZQFcJOecTXIdGC9AEBOfZkWlETMKYsC7qRJhVc/export?format=csv&gid=969973391', 0),
    ('Sheet 1 (N col)', 'https://docs.google.com/spreadsheets/d/1tjiYmZQFcJOecTXIdGC9AEBOfZkWlETMKYsC7qRJhVc/export?format=csv&gid=969973391', 13),
    ('Sheet 2 (A col)', 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/export?format=csv&gid=1781095899', 0),
    ('Sheet 2 (O col)', 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/export?format=csv&gid=1781095899', 14),
]

for label, url, col_idx in urls:
    req = urllib.request.urlopen(url)
    rows = list(csv.reader(req.read().decode('utf-8').splitlines()))
    months = defaultdict(int)
    unparsed = 0
    for r in rows[2:]:
        if len(r) > col_idx and r[col_idx].strip():
            val = r[col_idx].strip()
            dt = parse_date(val)
            if dt:
                if dt >= datetime.datetime(2026, 3, 1):
                    ym = dt.strftime('%Y-%m')
                    months[ym] += 1
            else:
                unparsed += 1
    print(f'=== {label} (2026/03 onwards) ===')
    for ym in sorted(months.keys()):
        print(f'  {ym}: {months[ym]}')
    print(f'  Unparsed/Skipped before 2026-03: {unparsed}')
"

