import urllib.request
import csv
import datetime
from collections import defaultdict

def parse_date(s):
    s = s.strip()
    for fmt in ('%Y/%m/%d', '%Y-%m-%d', '%m/%d', '%Y/%m/%d %H:%M:%S', '%Y-%m-%d %H:%M:%S'):
        try:
            dt = datetime.datetime.strptime(s, fmt)
            if dt.year == 1900:
                dt = dt.replace(year=2026)
            return dt
        except ValueError:
            continue
    parts = s.split('/')
    if len(parts) == 2:
        try:
            m = int(parts[0])
            d = int(parts[1])
            return datetime.datetime(2026, m, d)
        except ValueError:
            pass
    return None

# Sheet 1
url1 = 'https://docs.google.com/spreadsheets/d/1tjiYmZQFcJOecTXIdGC9AEBOfZkWlETMKYsC7qRJhVc/export?format=csv&gid=969973391'
rows1 = list(csv.reader(urllib.request.urlopen(url1).read().decode('utf-8').splitlines()))

s1_a = defaultdict(int)
s1_n = defaultdict(int)

for r in rows1[2:]:
    if len(r) > 0 and r[0].strip():
        dt = parse_date(r[0])
        if dt and dt >= datetime.datetime(2026, 3, 1):
            s1_a[dt.strftime('%Y-%m')] += 1
    if len(r) > 13 and r[13].strip():
        dt = parse_date(r[13])
        if dt and dt >= datetime.datetime(2026, 3, 1):
            s1_n[dt.strftime('%Y-%m')] += 1

# Sheet 2
url2 = 'https://docs.google.com/spreadsheets/d/1NQU2SGVykYL3n35NgzL78R0fszK0vt5yacNSV151wYI/export?format=csv&gid=1781095899'
rows2 = list(csv.reader(urllib.request.urlopen(url2).read().decode('utf-8').splitlines()))

s2_a = defaultdict(int)
s2_o = defaultdict(int)

for r in rows2[2:]:
    if len(r) > 0 and r[0].strip():
        dt = parse_date(r[0])
        if dt and dt >= datetime.datetime(2026, 3, 1):
            s2_a[dt.strftime('%Y-%m')] += 1
    if len(r) > 14 and r[14].strip():
        dt = parse_date(r[14])
        if dt and dt >= datetime.datetime(2026, 3, 1):
            s2_o[dt.strftime('%Y-%m')] += 1

all_months = sorted(list(set(list(s1_a.keys()) + list(s1_n.keys()) + list(s2_a.keys()) + list(s2_o.keys()))))

print('Month\tSheet1(Col A)\tSheet2(Col A)\tSum(Col A)\tSheet1(Col N)\tSheet2(Col O)\tSum(Col N/O)')
for m in all_months:
    a1 = s1_a[m]
    a2 = s2_a[m]
    sum_a = a1 + a2
    n1 = s1_n[m]
    o2 = s2_o[m]
    sum_n = n1 + o2
    print(f'{m}\t{a1}\t\t{a2}\t\t{sum_a}\t\t{n1}\t\t{o2}\t\t{sum_n}')
